package com.chatq.keyboardtests;
import android.app.*;import android.content.*;import android.net.Uri;import java.io.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.json.*;
/** Real shipping picker processing, only own synthetic MediaStore documents; no user files. */
final class AttachmentChecks {
 static int checks;static void expect(boolean ok,String text){if(!ok)throw new AssertionError(text);checks++;}
 static int run(final Instrumentation instrumentation)throws Exception{
  final Context context=instrumentation.getTargetContext();final AtomicReference<ExportChecks.Picker> host=new AtomicReference<>();instrumentation.runOnMainSync(new Runnable(){public void run(){ExportChecks.Picker picker=new ExportChecks.Picker();picker.context=context;host.set(picker);}});ExportChecks.Picker picker=host.get();ClassLoader loader=context.getClassLoader();Class<?> function=loader.loadClass("kotlin.jvm.functions.Function0"),promise=loader.loadClass("expo.modules.kotlin.Promise"),type=loader.loadClass("expo.modules.chatqkeyboard.ChatAttachments");Object factory=Proxy.newProxyInstance(loader,new Class<?>[]{function},new InvocationHandler(){public Object invoke(Object p,Method m,Object[] a){return picker;}}),attachments=type.getConstructor(function).newInstance(factory);Method pick=type.getMethod("pick",String.class,promise),result=type.getMethod("result",int.class,int.class,Intent.class),destroy=type.getMethod("destroy");ArrayList<Uri> documents=new ArrayList<>();
  try{
   for(int n=0;n<8;n++){
    ExportChecks.Result state=new ExportChecks.Result();Object proxy=Proxy.newProxyInstance(loader,new Class<?>[]{promise},state);picker.opened=new CountDownLatch(1);pick.invoke(attachments,"file",proxy);expect(picker.opened.await(3,TimeUnit.SECONDS),"explicit document selection launches");int code=picker.code;expect(picker.intent.getAction().equals(Intent.ACTION_OPEN_DOCUMENT),"no broad file permission");result.invoke(attachments,code-1,Activity.RESULT_CANCELED,null);expect(state.calls.get()==0,"stale result ignored");
    if(n==0){result.invoke(attachments,code,Activity.RESULT_CANCELED,null);expect(state.done.await(2,TimeUnit.SECONDS)&&state.value==null,"cancel returns no attachment");continue;}
    if(n==7){destroy.invoke(attachments);expect(state.done.await(2,TimeUnit.SECONDS)&&state.value==null,"destroy releases pending selection");result.invoke(attachments,code,Activity.RESULT_OK,new Intent().setData(Uri.parse("content://invalid/late")));expect(state.calls.get()==1,"late result cannot settle destroyed job");continue;}
    String name="ChatQ-attachment-fixture-"+System.nanoTime()+".txt",mime="text/plain";byte[] bytes;
    if(n==1)bytes="\uFEFF合成 UTF-8 文本🙂".getBytes("UTF-8");else if(n==2)bytes=new byte[]{(byte)255};else if(n==3)bytes=new byte[48001];else if(n==4){name+=".pdf";mime="application/pdf";bytes="%PDF-1.7\nfixture-only".getBytes("UTF-8");}else if(n==5){mime="image/jpeg";name+=".jpg";android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(2500,1400,android.graphics.Bitmap.Config.ARGB_8888);ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(android.graphics.Bitmap.CompressFormat.JPEG,90,out);bitmap.recycle();bytes=out.toByteArray();}else{mime="application/pdf";name+=".pdf";bytes=new byte[512001];System.arraycopy("%PDF-".getBytes("UTF-8"),0,bytes,0,5);}
    ContentValues values=new ContentValues();values.put("_display_name",name);values.put("mime_type",mime);values.put("relative_path","Download/");Uri uri=context.getContentResolver().insert(android.provider.MediaStore.Downloads.EXTERNAL_CONTENT_URI,values);documents.add(uri);try(OutputStream out=context.getContentResolver().openOutputStream(uri)){out.write(bytes);}result.invoke(attachments,code,Activity.RESULT_OK,new Intent().setData(uri));expect(state.done.await(8,TimeUnit.SECONDS),"bounded attachment read completes");
    if(n==2||n==3||n==6){expect(state.error!=null&&state.value==null,"invalid UTF-8 / oversized text / oversized PDF rejected");}else{expect(state.error==null,"valid attachment accepted: "+state.error);JSONObject value=new JSONObject(state.value);if(n==1)expect(value.getString("content").equals("合成 UTF-8 文本🙂")&&value.getString("mime").equals("text/plain"),"UTF-8 and BOM normalized");if(n==4)expect(value.getString("mime").equals("application/pdf")&&value.getString("content").startsWith("data:application/pdf;base64,"),"PDF data URL generated");if(n==5){byte[] jpg=android.util.Base64.decode(value.getString("content").split(",")[1],0);android.graphics.BitmapFactory.Options options=new android.graphics.BitmapFactory.Options();options.inJustDecodeBounds=true;android.graphics.BitmapFactory.decodeByteArray(jpg,0,jpg.length,options);expect(jpg.length<=512000&&Math.max(options.outWidth,options.outHeight)<=1280,"image downsampled and compressed within payload budget");}}
    result.invoke(attachments,code,Activity.RESULT_CANCELED,null);expect(state.calls.get()==1,"result settles once");
   }
   return checks;
  }finally{destroy.invoke(attachments);for(Uri uri:documents)context.getContentResolver().delete(uri,null,null);}
 }
}
